mapper.update:
UPDATE bd_course_time
SET remaining_number = remaining_number + #{num},
    total_number = total_number + #{num},
    update_time = NOW(),
    update_by = #{userId}
WHERE id = #{id}

mapper.select:
SELECT 
FROM bd_course_time
WHERE student_id = #{studentId}
  AND course_id = #{courseId}
  AND is_delete = 0
FOR UPDATE
